_WEIGHTS=np.asarray(COEF,np.float32)
_BIAS=np.asarray(INTERCEPT,np.float32)
def predict_category(vector):
    vector=np.asarray(vector,np.float32)
    if vector.shape!=(512,) or not np.isfinite(vector).all():
        raise ValueError('Invalid photo features')
    norm=float(np.linalg.norm(vector))
    if norm<=0:raise ValueError('Empty photo features')
    logits=_WEIGHTS@(vector/norm)+_BIAS
    scores=np.exp(logits-logits.max());scores/=scores.sum()
    best=int(scores.argmax());score=float(scores[best])
    return dict(category=CLASSES[best] if score>=THRESHOLD else 'unclear',category_score=round(score,6),head_version=HEAD_VERSION)
